#!/usr/bin/env python3
"""Pionex grid app + local relay in ONE file (Python 3 standard library only).
Calls to Pionex come from THIS device's own IP, not a shared cloud IP.
Run:  python pionex_local.py        then open  http://127.0.0.1:8787  in Chrome.
Keys stay in the browser; this server never stores them. Listens on 127.0.0.1 only."""
import base64, json, sys, time, urllib.request, urllib.error
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

UP = "https://api.pionex.com"
PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 8787
UA = "Mozilla/5.0 (Linux; Android 14) PionexGrid/1.0"
HTML = base64.b64decode("")

class H(BaseHTTPRequestHandler):
    def log_message(self, *a): pass
    def _send(self, code, body, ctype="application/json"):
        self.send_response(code)
        for k, v in (("Content-Type", ctype), ("Cache-Control", "no-store"),
                     ("Access-Control-Allow-Origin", "*"),
                     ("Access-Control-Allow-Headers", "PIONEX-KEY,PIONEX-SIGNATURE,Content-Type"),
                     ("Access-Control-Allow-Methods", "GET,POST,DELETE,OPTIONS"),
                     ("Access-Control-Allow-Private-Network", "true"),
                     ("Content-Length", str(len(body)))):
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)
    def _fetch(self, path, method="GET", data=None, headers=None):
        h = {"User-Agent": UA}; h.update(headers or {})
        try:
            r = urllib.request.urlopen(urllib.request.Request(UP + path, data=data, headers=h, method=method), timeout=20)
            return r.status, r.read()
        except urllib.error.HTTPError as e:
            return e.code, e.read()
    def do_OPTIONS(self): self._send(204, b"")
    def _relay(self):
        n = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(n) if n else None
        h = {k: self.headers.get(k) for k in ("PIONEX-KEY", "PIONEX-SIGNATURE", "Content-Type") if self.headers.get(k)}
        try: code, tx = self._fetch(self.path, self.command, body, h)
        except Exception as e:
            return self._send(502, json.dumps({"result": False, "code": "RELAY_UPSTREAM_FAIL", "message": str(e)}).encode())
        try: json.loads(tx)
        except Exception:
            tx = json.dumps({"result": False, "code": "HTTP_%d" % code, "message": tx[:200].decode("utf8", "replace")}).encode()
        self._send(code, tx)
    do_POST = do_DELETE = _relay
    def do_GET(self):
        p = self.path
        if p.startswith("/api/"): return self._relay()
        if p.startswith("/diag"):
            if "ping=1" in p: return self._send(200, b'{"ok":true,"status":200,"ping":true}')
            t = time.time()
            try:
                code, tx = self._fetch("/api/v1/market/bookTickers?symbol=BTC_USDT_PERP")
                out = {"ok": code == 200, "status": code, "ms": int((time.time() - t) * 1000), "ip": "local device", "head": tx[:100].decode("utf8", "replace")}
            except Exception as e:
                out = {"ok": False, "status": 0, "ip": "local device", "error": str(e)}
            return self._send(200, json.dumps(out).encode())
        self._send(200, HTML, "text/html; charset=utf-8")

if __name__ == "__main__":
    print("Pionex grid running. Open http://127.0.0.1:%d in Chrome. Ctrl+C to stop." % PORT)
    ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
